D.Quests[32167]={Title="远古的败亡",Objectives="去卡桑琅丛林的统御岗哨与乔恩·星眼谈一谈。",Description="这只仙鹤已经倒下了。"}
D.Quests[32168]={Title="老猫的末日",Objectives="去卡桑琅丛林的统御岗哨与乔恩·星眼谈一谈。",Description="这只老虎已经倒下了。"}
